package com.bank.revenue.service;

import com.bank.revenue.dto.MonthlyRevenue;
import com.bank.revenue.model.Order;
import com.bank.revenue.repository.OrderRepository;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class RevenueReportService {
    private static final Logger log = Logger.getLogger(RevenueReportService.class.getName());
    private final OrderRepository repo;

    public RevenueReportService(OrderRepository repo) { this.repo = repo; }

    // Java equivalent of: GROUP BY year, month SUM(total_amount) ORDER BY year, month
    public List<MonthlyRevenue> monthlyRevenue() {
        Map<String, BigDecimal> buckets = new TreeMap<>(); // TreeMap keeps keys sorted
        for (Order o : repo.findAll()) {
            int yr = o.getOrderDate().getYear();
            int mon = o.getOrderDate().getMonthValue();
            String key = String.format("%04d-%02d", yr, mon); // "2025-01"
            buckets.merge(key, o.getTotalAmount(), BigDecimal::add); // SUM within the group
        }
        List<MonthlyRevenue> result = new ArrayList<>();
        for (Map.Entry<String, BigDecimal> e : buckets.entrySet()) {
            String[] parts = e.getKey().split("-");
            result.add(new MonthlyRevenue(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), e.getValue()));
        }
        log.info(() -> "Built monthly revenue report with " + result.size() + " months");
        return result;
    }
}
